/**
* Generate test fixtures from stdlib's own C implementation on the shared inputs in `../../inputs/`.
*
* ## Notes
*
* -   Run this script from the directory in which fixtures should be written.
* -   Inputs are read from the shared input files (`*.json`). Each number is parsed with `strtod`, which rounds to the nearest double, and `"NaN"`, `"Infinity"`, and `"-Infinity"` are mapped to the corresponding values. Each fixture's `meta.inputs` is the SHA-256 of the input file it read.
* -   Values are written with `%.17g`, which round-trips every double, and non-finite values as the same strings.
* -   The runner calls `stdlib_base_log1p`, compiled with its dependencies from the sources the package's `manifest.json` lists, so no Node.js add-on is needed.
*/
#include "stdlib/math/base/special/log1p.h"
#include <stdlib.h>
#include <stdio.h>
#include <string.h>
#include <stdint.h>
#include <float.h>
#include <time.h>
#include <math.h>
#ifdef __GLIBC__
#include <gnu/libc-version.h>
#endif

#ifndef STDLIB_COMMIT
#define STDLIB_COMMIT ""
#endif

#ifndef RUNNER_CFLAGS
#define RUNNER_CFLAGS ""
#endif

// Directory containing the shared inputs:
static const char *INPUTS = "../../inputs";

// Shared input files, by regime:
static const char *REGIMES[] = {
	"big_positive",
	"edge_cases",
	"huge_positive",
	"large_negative",
	"large_positive",
	"medium_negative",
	"medium_positive",
	"small_negative",
	"small_positive",
	"tiny_negative",
	"tiny_positive"
};

/**
* Computes the SHA-256 digest of a byte array, as a lowercase hexadecimal string.
*
* @param data   bytes
* @param len    number of bytes
* @param out    output buffer (at least 65 bytes)
*/
static void sha256( const unsigned char *data, const size_t len, char *out ) {
	static const uint32_t K[ 64 ] = {
		0x428a2f98, 0x71374491, 0xb5c0fbcf, 0xe9b5dba5, 0x3956c25b, 0x59f111f1, 0x923f82a4, 0xab1c5ed5,
		0xd807aa98, 0x12835b01, 0x243185be, 0x550c7dc3, 0x72be5d74, 0x80deb1fe, 0x9bdc06a7, 0xc19bf174,
		0xe49b69c1, 0xefbe4786, 0x0fc19dc6, 0x240ca1cc, 0x2de92c6f, 0x4a7484aa, 0x5cb0a9dc, 0x76f988da,
		0x983e5152, 0xa831c66d, 0xb00327c8, 0xbf597fc7, 0xc6e00bf3, 0xd5a79147, 0x06ca6351, 0x14292967,
		0x27b70a85, 0x2e1b2138, 0x4d2c6dfc, 0x53380d13, 0x650a7354, 0x766a0abb, 0x81c2c92e, 0x92722c85,
		0xa2bfe8a1, 0xa81a664b, 0xc24b8b70, 0xc76c51a3, 0xd192e819, 0xd6990624, 0xf40e3585, 0x106aa070,
		0x19a4c116, 0x1e376c08, 0x2748774c, 0x34b0bcb5, 0x391c0cb3, 0x4ed8aa4a, 0x5b9cca4f, 0x682e6ff3,
		0x748f82ee, 0x78a5636f, 0x84c87814, 0x8cc70208, 0x90befffa, 0xa4506ceb, 0xbef9a3f7, 0xc67178f2
	};
	uint32_t h[ 8 ] = { 0x6a09e667, 0xbb67ae85, 0x3c6ef372, 0xa54ff53a, 0x510e527f, 0x9b05688c, 0x1f83d9ab, 0x5be0cd19 };
	uint64_t bits = (uint64_t)len * 8;
	unsigned char *msg;
	size_t mlen;
	uint32_t w[ 64 ];
	uint32_t a, b, c, d, e, f, g, k, t1, t2;
	size_t i;
	int j;

	// Pad the message: append 0x80, zeros to 56 bytes mod 64, and the bit length as a big-endian 64-bit integer:
	mlen = len + 1;
	while ( mlen % 64 != 56 ) {
		mlen += 1;
	}
	mlen += 8;
	msg = (unsigned char *)calloc( mlen, 1 );
	if ( msg == NULL ) {
		fprintf( stderr, "out of memory\n" );
		exit( 1 );
	}
	memcpy( msg, data, len );
	msg[ len ] = 0x80;
	for ( j = 0; j < 8; j++ ) {
		msg[ mlen-1-j ] = (unsigned char)( bits >> (j*8) );
	}
	#define ROTR( x, n ) ( ( (x) >> (n) ) | ( (x) << (32-(n)) ) )
	for ( i = 0; i < mlen; i += 64 ) {
		for ( j = 0; j < 16; j++ ) {
			w[ j ] = ( (uint32_t)msg[ i+(j*4) ] << 24 ) | ( (uint32_t)msg[ i+(j*4)+1 ] << 16 ) | ( (uint32_t)msg[ i+(j*4)+2 ] << 8 ) | (uint32_t)msg[ i+(j*4)+3 ];
		}
		for ( j = 16; j < 64; j++ ) {
			w[ j ] = w[ j-16 ] + ( ROTR( w[ j-15 ], 7 ) ^ ROTR( w[ j-15 ], 18 ) ^ ( w[ j-15 ] >> 3 ) ) + w[ j-7 ] + ( ROTR( w[ j-2 ], 17 ) ^ ROTR( w[ j-2 ], 19 ) ^ ( w[ j-2 ] >> 10 ) );
		}
		a = h[ 0 ]; b = h[ 1 ]; c = h[ 2 ]; d = h[ 3 ]; e = h[ 4 ]; f = h[ 5 ]; g = h[ 6 ]; k = h[ 7 ];
		for ( j = 0; j < 64; j++ ) {
			t1 = k + ( ROTR( e, 6 ) ^ ROTR( e, 11 ) ^ ROTR( e, 25 ) ) + ( ( e & f ) ^ ( ~e & g ) ) + K[ j ] + w[ j ];
			t2 = ( ROTR( a, 2 ) ^ ROTR( a, 13 ) ^ ROTR( a, 22 ) ) + ( ( a & b ) ^ ( a & c ) ^ ( b & c ) );
			k = g; g = f; f = e; e = d + t1; d = c; c = b; b = a; a = t1 + t2;
		}
		h[ 0 ] += a; h[ 1 ] += b; h[ 2 ] += c; h[ 3 ] += d; h[ 4 ] += e; h[ 5 ] += f; h[ 6 ] += g; h[ 7 ] += k;
	}
	#undef ROTR
	free( msg );
	for ( j = 0; j < 8; j++ ) {
		snprintf( out+(j*8), 9, "%08x", (unsigned int)h[ j ] );
	}
}

/**
* Reads a file into a NUL-terminated buffer.
*
* @param path   file path
* @param size   output argument for the number of bytes read
* @return       buffer
*/
static char * read_file( const char *path, size_t *size ) {
	char *buf;
	long n;
	FILE *f;

	f = fopen( path, "rb" );
	if ( f == NULL ) {
		fprintf( stderr, "unable to open %s\n", path );
		exit( 1 );
	}
	fseek( f, 0, SEEK_END );
	n = ftell( f );
	fseek( f, 0, SEEK_SET );
	buf = (char *)malloc( (size_t)n + 1 );
	if ( buf == NULL || fread( buf, 1, (size_t)n, f ) != (size_t)n ) {
		fprintf( stderr, "unable to read %s\n", path );
		exit( 1 );
	}
	buf[ n ] = '\0';
	fclose( f );
	*size = (size_t)n;
	return buf;
}

/**
* Skips JSON whitespace.
*
* @param p   pointer into a JSON document
* @return    pointer to the next non-whitespace character
*/
static const char * skip_ws( const char *p ) {
	while ( *p == ' ' || *p == '\n' || *p == '\r' || *p == '\t' ) {
		p++;
	}
	return p;
}

/**
* Reads the `"x"` array of a shared input file.
*
* ## Notes
*
* -   The shared input files are written by `scripts/inputs.js` with `"x"` as the first array, so the first occurrence of the key is the array. The function exits on anything it does not expect, rather than guessing.
*
* @param json   JSON document
* @param path   file path, for error messages
* @param len    output argument for the number of values
* @return       values
*/
static double * read_inputs( const char *json, const char *path, size_t *len ) {
	const char *p;
	double *out;
	double *tmp;
	size_t cap;
	char *end;

	p = strstr( json, "\"x\"" );
	if ( p == NULL ) {
		fprintf( stderr, "%s: no \"x\" array\n", path );
		exit( 1 );
	}
	p = skip_ws( p + 3 );
	if ( *p != ':' ) {
		fprintf( stderr, "%s: expected ':' after \"x\"\n", path );
		exit( 1 );
	}
	p = skip_ws( p + 1 );
	if ( *p != '[' ) {
		fprintf( stderr, "%s: expected '[' after \"x\":\n", path );
		exit( 1 );
	}
	p++;
	cap = 1024;
	out = (double *)malloc( cap * sizeof( double ) );
	if ( out == NULL ) {
		fprintf( stderr, "out of memory\n" );
		exit( 1 );
	}
	*len = 0;
	while ( 1 ) {
		p = skip_ws( p );
		if ( *p == ']' ) {
			break;
		}
		if ( *len == cap ) {
			cap *= 2;
			tmp = (double *)realloc( out, cap * sizeof( double ) );
			if ( tmp == NULL ) {
				free( out );
				fprintf( stderr, "out of memory\n" );
				exit( 1 );
			}
			out = tmp;
		}
		if ( *p == '"' ) {
			if ( strncmp( p, "\"NaN\"", 5 ) == 0 ) {
				out[ *len ] = NAN;
				p += 5;
			} else if ( strncmp( p, "\"Infinity\"", 10 ) == 0 ) {
				out[ *len ] = HUGE_VAL;
				p += 10;
			} else if ( strncmp( p, "\"-Infinity\"", 11 ) == 0 ) {
				out[ *len ] = -HUGE_VAL;
				p += 11;
			} else {
				fprintf( stderr, "%s: unexpected string at element %lu\n", path, (unsigned long)*len );
				exit( 1 );
			}
		} else {
			out[ *len ] = strtod( p, &end );
			if ( end == p ) {
				fprintf( stderr, "%s: unparseable element %lu\n", path, (unsigned long)*len );
				exit( 1 );
			}
			p = end;
		}
		*len += 1;
		p = skip_ws( p );
		if ( *p == ',' ) {
			p++;
		} else if ( *p != ']' ) {
			fprintf( stderr, "%s: expected ',' or ']' after element %lu\n", path, (unsigned long)*len );
			exit( 1 );
		}
	}
	return out;
}

/**
* Writes a double to a file as a JSON value, matching the shared input files.
*
* @param f   file to write to
* @param x   value
*/
static void write_f64( FILE *f, const double x ) {
	if ( isnan( x ) ) {
		fprintf( f, "\"NaN\"" );
	} else if ( isinf( x ) ) {
		fprintf( f, ( x > 0.0 ) ? "\"Infinity\"" : "\"-Infinity\"" );
	} else {
		fprintf( f, "%.17g", x );
	}
}

/**
* Writes a named array of doubles.
*
* @param f      file to write to
* @param name   key
* @param x      values
* @param len    number of values
*/
static void write_array( FILE *f, const char *name, const double *x, const size_t len ) {
	size_t i;

	fprintf( f, "\"%s\":[", name );
	for ( i = 0; i < len; i++ ) {
		if ( i > 0 ) {
			fprintf( f, "," );
		}
		write_f64( f, x[ i ] );
	}
	fprintf( f, "]" );
}

/**
* Reads a shared input file, and writes fixtures to a JSON file of the same name.
*
* @param regime   regime name
*/
static void gen( const char *regime ) {
	char inpath[ 256 ];
	char outpath[ 256 ];
	char digest[ 65 ];
	char ts[ 32 ];
	double *x;
	double *y;
	char *json;
	size_t size;
	size_t len;
	size_t i;
	time_t now;
	FILE *f;

	snprintf( inpath, sizeof( inpath ), "%s/%s.json", INPUTS, regime );
	snprintf( outpath, sizeof( outpath ), "%s.json", regime );
	json = read_file( inpath, &size );
	sha256( (const unsigned char *)json, size, digest );
	x = read_inputs( json, inpath, &len );
	free( json );

	y = (double *)malloc( ( ( len > 0 ) ? len : 1 ) * sizeof( double ) );
	if ( y == NULL ) {
		fprintf( stderr, "out of memory\n" );
		exit( 1 );
	}
	for ( i = 0; i < len; i++ ) {
		y[ i ] = stdlib_base_log1p( x[ i ] );
	}
	now = time( NULL );
	strftime( ts, sizeof( ts ), "%Y-%m-%dT%H:%M:%SZ", gmtime( &now ) );

	f = fopen( outpath, "w" );
	if ( f == NULL ) {
		fprintf( stderr, "unable to open %s\n", outpath );
		exit( 1 );
	}
	fprintf( f, "{" );
	write_array( f, "x", x, len );
	fprintf( f, "," );
	write_array( f, "expected", y, len );
	fprintf( f, ",\"meta\":{" );
	fprintf( f, "\"source\":\"c::stdlib\"," );
	fprintf( f, "\"function\":\"stdlib_base_log1p\"," );
	fprintf( f, "\"implementation\":\"stdlib's own C (src/main.c), a port of FDLIBM's s_log1p.c\"," );
	fprintf( f, "\"versions\":{\"stdlib\":\"%s\"},", STDLIB_COMMIT );
	fprintf( f, "\"platform\":{" );
#if defined( __linux__ )
	fprintf( f, "\"os\":\"linux\"," );
#elif defined( __APPLE__ )
	fprintf( f, "\"os\":\"darwin\"," );
#else
	fprintf( f, "\"os\":null," );
#endif
#if defined( __x86_64__ )
	fprintf( f, "\"arch\":\"x86_64\"," );
#elif defined( __aarch64__ )
	fprintf( f, "\"arch\":\"aarch64\"," );
#else
	fprintf( f, "\"arch\":null," );
#endif
#if defined( __clang__ )
	fprintf( f, "\"compiler\":\"clang %s, %s\",", __clang_version__, RUNNER_CFLAGS );
#elif defined( __GNUC__ )
	fprintf( f, "\"compiler\":\"gcc %s, %s\",", __VERSION__, RUNNER_CFLAGS );
#else
	fprintf( f, "\"compiler\":null," );
#endif
#ifdef __GLIBC__
	fprintf( f, "\"libc\":\"glibc %s\"},", gnu_get_libc_version() );
#else
	fprintf( f, "\"libc\":null}," );
#endif
	fprintf( f, "\"generated\":\"%s\",", ts );
	fprintf( f, "\"inputs\":\"%s\",", digest );
	fprintf( f, "\"regime\":\"%s\"}}\n", regime );
	fclose( f );
	free( x );
	free( y );
}

/**
* Main execution sequence.
*/
int main( void ) {
	size_t i;

	for ( i = 0; i < sizeof( REGIMES ) / sizeof( REGIMES[ 0 ] ); i++ ) {
		gen( REGIMES[ i ] );
	}
	return 0;
}
